; DOS U preset: Laura Bow 1 (The Colonel's Bequest), Korean EUC-KR patch.
; Legacy (EUC-KR) text path uses singleFace(), the first face only, so only
; KOCP949.SVF (NanumGothic-Bold, 16 px, 2 bpp, ASCII + cp949, one baseline
; in a 16x16 cell - bake-dos-fonts.sh) is active here, for every font id;
; the body face KOBATANG.SVF needs a UTF-8 translation (see KQ1KOU.MAP).
; Characters KOCP949 lacks draw U+25A1. align=cell: the 16-row glyph sits
; on the 16-row line with no offset, nothing above or below it for the
; game to leave behind when it erases the line. rgb_rendering=true
; (scummvm.ini) is what makes this render truecolor/antialiased; alpha=
; below is documentation only, SCI ignores it (spec 4.5).
[hires]
scale=2
alpha=true
face=ko
missing=u+25a1
align=cell

[fonts]
ko=KOCP949.SVF

[latin]
mode=proportional
metrics=font
